def render_sidebar_and_get_lang() -> tuple:
    """Renders the translated EIU logo, language selector, holiday theme & music, and disclaimer in the sidebar."""
    if st.session_state.get("_sidebar_done", False):
        lang_code = LANGUAGES[st.session_state.get("lang_choice", "🇻🇳 Tiếng Việt")]
        return lang_code, TRANSLATIONS[lang_code]

    if "lang_choice" not in st.session_state:
        st.session_state["lang_choice"] = "🇻🇳 Tiếng Việt"
    if "active_theme" not in st.session_state:
        st.session_state["active_theme"] = "xmas"

    # 1. EIU Logo Card at top of Sidebar (Translated!)
    logo_slot = st.sidebar.empty()

    # 2. Smart Compact Language Switcher
    _cur_choice = st.session_state.get("_lang_select_widget", st.session_state["lang_choice"])
    if _cur_choice not in LANGUAGES:
        _cur_choice = "🇻🇳 Tiếng Việt"
    cur_lang = LANGUAGES[_cur_choice]
    _, _, _, lang_lbl, _ = LOGO_TEXT_I18N.get(cur_lang, LOGO_TEXT_I18N["en"])

    selected_label = st.sidebar.selectbox(
        lang_lbl,
        options=list(LANGUAGES.keys()),
        index=list(LANGUAGES.keys()).index(_cur_choice),
        key="_lang_select_widget",
    )
    st.session_state["lang_choice"] = selected_label
    lang_code = LANGUAGES[selected_label]
    t = TRANSLATIONS[lang_code]
    uni_title, uni_sub, _, _, _ = LOGO_TEXT_I18N.get(lang_code, LOGO_TEXT_I18N["en"])
    th_cfg = THEME_I18N.get(lang_code, THEME_I18N["en"])

    # 2b. Holiday Theme Selector (Tết ONLY for Vietnamese & Chinese!)
    if lang_code in ("vi", "zh"):
        theme_options = ["xmas", "tet", "standard"]
    else:
        theme_options = ["xmas", "standard"]

    if st.session_state["active_theme"] not in theme_options:
        st.session_state["active_theme"] = "xmas"

    theme_labels = {
        "standard": th_cfg["opt_standard"],
        "xmas": th_cfg["opt_xmas"],
        "tet": th_cfg["opt_tet"],
    }
    chosen_theme = st.sidebar.selectbox(
        th_cfg["label"],
        options=theme_options,
        index=theme_options.index(st.session_state["active_theme"]),
        format_func=lambda k: theme_labels[k],
        key="_theme_select_widget",
    )
    st.session_state["active_theme"] = chosen_theme

    # 2c. Holiday Instrumental Music Player (uses user's custom xmas_music.m4a / tet_music.m4a with online fallback)
    if chosen_theme in ("xmas", "tet"):
        m_title = th_cfg["xmas_music"] if chosen_theme == "xmas" else th_cfg["tet_music"]
        m_border = "#fecdd3" if chosen_theme == "xmas" else "#fcd34d"
        m_bg = "#fff5f5" if chosen_theme == "xmas" else "#fffbeb"
        m_color = "#b91c1c" if chosen_theme == "xmas" else "#92400e"

        _fname = "xmas_music.m4a" if chosen_theme == "xmas" else "tet_music.m4a"
        _base = Path(__file__).resolve().parent
        _music_path = None
        for _cand in [_base / _fname, _base / "assets" / _fname, _base.parent / _fname, _base.parent / "assets" / _fname]:
            if _cand.exists():
                _music_path = _cand
                break

        import base64 as _b64
        _music_bytes = (
            _music_path.read_bytes()
            if _music_path is not None
            else _b64.b64decode(XMAS_MUSIC_B64 if chosen_theme == "xmas" else TET_MUSIC_B64)
        )
        st.sidebar.markdown(
            f"<div style='background:{m_bg}; border:1px solid {m_border}; border-radius:10px; padding:6px 10px; margin-bottom:4px; "
            f"font-size:0.75rem; font-weight:700; color:{m_color};'>{m_title}</div>",
            unsafe_allow_html=True,
        )
        st.sidebar.audio(_music_bytes, format="audio/mp4", loop=True)

    if chosen_theme == "xmas":
        inject_christmas_theme()
        logo_slot.markdown(
            f"<div style='background:linear-gradient(180deg,#ffffff 0%,#fff5f5 100%); padding:12px 14px 12px 14px; "
            f"border-radius:16px; border:1.5px solid #fecdd3; text-align:center; margin-bottom:10px; "
            f"box-shadow:0 4px 12px rgba(220,38,38,0.08);'>"
            f"<div class='xmas-candy-strip'></div>"
            f"<img src='data:image/png;base64,{EIU_LOGO_B64}' style='max-width:158px; height:auto; margin-bottom:6px;'/>"
            f"<div style='font-size:0.74rem; font-weight:800; color:#b91c1c; letter-spacing:0.3px; line-height:1.3;'>{uni_title}</div>"
            f"<div style='font-size:0.7rem; font-weight:600; color:#15803d; margin-top:2px;'>{uni_sub}</div>"
            f"<div style='margin-top:8px; display:inline-block; background:#fef2f2; border:1px solid #fca5a5; "
            f"color:#b91c1c; font-size:0.68rem; font-weight:700; padding:3px 9px; border-radius:999px;'>"
            f"{th_cfg['xmas_side']}</div>"
            f"</div>",
            unsafe_allow_html=True,
        )
    elif chosen_theme == "tet":
        inject_tet_theme()
        logo_slot.markdown(
            f"<div style='background:linear-gradient(180deg,#ffffff 0%,#fffbeb 100%); padding:12px 14px 12px 14px; "
            f"border-radius:16px; border:1.5px solid #fcd34d; text-align:center; margin-bottom:10px; "
            f"box-shadow:0 4px 12px rgba(185,28,28,0.09);'>"
            f"<div class='tet-gold-strip'></div>"
            f"<img src='data:image/png;base64,{EIU_LOGO_B64}' style='max-width:158px; height:auto; margin-bottom:6px;'/>"
            f"<div style='font-size:0.74rem; font-weight:800; color:#b91c1c; letter-spacing:0.3px; line-height:1.3;'>{uni_title}</div>"
            f"<div style='font-size:0.7rem; font-weight:600; color:#b45309; margin-top:2px;'>{uni_sub}</div>"
            f"<div style='margin-top:8px; display:inline-block; background:#fef2f2; border:1px solid #fbbf24; "
            f"color:#b91c1c; font-size:0.68rem; font-weight:700; padding:3px 9px; border-radius:999px;'>"
            f"{th_cfg['tet_side']}</div>"
            f"</div>",
            unsafe_allow_html=True,
        )
    else:
        logo_slot.markdown(
            f"<div style='background:#ffffff; padding:14px 14px 12px 14px; border-radius:14px; border:1.5px solid #cbd5e1; "
            f"text-align:center; margin-bottom:10px; box-shadow:0 3px 10px rgba(15,23,42,0.04);'>"
            f"<img src='data:image/png;base64,{EIU_LOGO_B64}' style='max-width:165px; height:auto; margin-bottom:6px;'/>"
            f"<div style='font-size:0.74rem; font-weight:800; color:#1e3a8a; letter-spacing:0.3px; line-height:1.3;'>{uni_title}</div>"
            f"<div style='font-size:0.7rem; font-weight:600; color:#475569; margin-top:2px;'>{uni_sub}</div>"
            f"</div>",
            unsafe_allow_html=True,
        )

    # 3. Placeholder for Navigation Menu (populated by app.py if in flat mode)
    st.session_state["_nav_placeholder"] = st.sidebar.container()

    # 4. Educational Disclaimer Box at bottom
    st.sidebar.markdown(
        f"<div class='edu-warning-box'>{t['disclaimer_box']}</div>",
        unsafe_allow_html=True,
    )
    st.session_state["_sidebar_done"] = True
    return lang_code, t


@st.cache_resource
def load_artifacts():
    base_dir = Path(__file__).resolve().parent

    def find_file(subpath: str, filename: str) -> Path:
        for candidate in [
            base_dir / subpath / filename,
            base_dir / filename,
            base_dir.parent / subpath / filename,
            base_dir.parent / filename,
        ]:
            if candidate.exists():
                return candidate
        return base_dir / subpath / filename

    meta_path = find_file("models", "model_meta.json")
    inydb_path = find_file("models", "inydb")
    pipeline_path = find_file("models", "pipeline.joblib")
    baseline_path = find_file("models", "baseline_logreg.joblib")

    try:
        with open(meta_path, "r", encoding="utf-8") as f:
            meta = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError, OSError) as exc:
        st.error(
            f"⚠️ Could not load model metadata (`models/model_meta.json`). "
            f"Please ensure `models/model_meta.json` is uploaded or run `python train.py`. ({exc})"
        )
        st.stop()

    main_pipe = None
    base_pipe = None
    try:
        import joblib
        try:
            if pipeline_path.exists():
                main_pipe = joblib.load(pipeline_path)
            elif inydb_path.exists():
                main_pipe = joblib.load(inydb_path)
        except Exception:
            main_pipe = None

        try:
            if baseline_path.exists():
                base_pipe = joblib.load(baseline_path)
        except Exception:
            base_pipe = None
    except Exception:
        main_pipe = None
        base_pipe = None

    return main_pipe, base_pipe, meta


def score_single_case(input_df: pd.DataFrame, main_pipe, base_pipe, meta: dict):
    ref = meta["explainability_reference"]
    weights = ref["feature_weights"]
    means = ref["feature_means"]
    stds = ref["feature_stds"]
    intercept = float(ref["logreg_intercept"])

    row = input_df.iloc[0]
    contributions = {}
    z_linear = intercept
    for feat, w in weights.items():
        val = float(row[feat])
        if feat in ["BMI", "Age", "GenHlth"]:
            standardized_diff = (val - float(means[feat])) / max(float(stds[feat]), 1e-6)
        else:
            standardized_diff = val - float(means[feat])
        contrib = float(w) * standardized_diff
        contributions[feat] = contrib
        z_linear += contrib

    z_safe = float(np.clip(z_linear, -30.0, 30.0))
    prob_lr = float(1.0 / (1.0 + np.exp(-z_safe)))
    synergy = 0.0
    if row["HighBP"] == 1 and row["HighChol"] == 1 and float(row["BMI"]) >= 28.0:
        synergy += 0.22
    if float(row["Age"]) >= 8 and float(row["GenHlth"]) >= 3:
        synergy += 0.14
    prob_gb = float(1.0 / (1.0 + np.exp(-float(np.clip(z_safe + synergy, -30.0, 30.0)))))

    # Prioritize direct scikit-learn pipeline output independently for each loaded model
    if main_pipe is not None:
        try:
            prob_gb = float(main_pipe.predict_proba(input_df)[0, 1])
        except Exception:
            pass
    if base_pipe is not None:
        try:
            prob_lr = float(base_pipe.predict_proba(input_df)[0, 1])
        except Exception:
            pass

    prob_gb = float(np.clip(prob_gb, 0.0, 1.0))
    prob_lr = float(np.clip(prob_lr, 0.0, 1.0))
    return prob_gb, prob_lr, contributions
